#pragma once
#include <Arduino.h>

/**
 * @brief Konvertiert eine 24-Bit-Hex-Farbe in eine 16-Bit-RGB565-Farbe.
 * 
 * @param hexColor Der 24-Bit-Farbwert (z.B. 0xA2B6D9).
 * @return uint16_t Die 16-Bit-Farbe im RGB565-Format.
 */
uint16_t hexToRGB565(uint32_t hexColor) {
    uint8_t r = (hexColor >> 16) & 0xFF;
    uint8_t g = (hexColor >> 8) & 0xFF;
    uint8_t b = hexColor & 0xFF;
    // Diese Konvertierung muss im Hauptprogramm erfolgen, wo dma_display verfügbar ist.
    // Hier definieren wir nur die Struktur.
    // In der Praxis wird das Array mit den bereits konvertierten Werten gefüllt.
    return ((r / 8) << 11) | ((g / 4) << 5) | (b / 8);
}

